package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.equals(double, double)
 * Designed to maximize branch and line coverage.
 */
public class MathUtils_equals_TriageGen4Test {

    @Test
    public void testEquals_SameValues() {
        // Test equality for standard numbers
        assertTrue("1.0 should equal 1.0", MathUtils.equals(1.0, 1.0));
        assertTrue("0.0 should equal 0.0", MathUtils.equals(0.0, 0.0));
        assertTrue("-5.5 should equal -5.5", MathUtils.equals(-5.5, -5.5));
        assertTrue("Large values should be equal", MathUtils.equals(Double.MAX_VALUE, Double.MAX_VALUE));
    }

    @Test
    public void testEquals_DifferentValues() {
        // Test inequality for standard numbers
        assertFalse("1.0 should not equal 2.0", MathUtils.equals(1.0, 2.0));
        assertFalse("Positive should not equal negative", MathUtils.equals(1.0, -1.0));
        assertFalse("Small difference should be false", MathUtils.equals(1.0, 1.000000000000001));
    }

    @Test
    public void testEquals_NaN() {
        // The method logic: (Double.isNaN(x) && Double.isNaN(y)) || x == y
        // Test both NaNs (should return true)
        assertTrue("NaN should equal NaN according to this implementation", MathUtils.equals(Double.NaN, Double.NaN));

        // Test one NaN and one number (should return false)
        assertFalse("NaN should not equal 1.0", MathUtils.equals(Double.NaN, 1.0));
        assertFalse("1.0 should not equal NaN", MathUtils.equals(1.0, Double.NaN));
    }

    @Test
    public void testEquals_SpecialValues() {
        // Test Infinity
        assertTrue("Positive Infinity should equal Positive Infinity", MathUtils.equals(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY));
        assertTrue("Negative Infinity should equal Negative Infinity", MathUtils.equals(Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY));
        assertFalse("Positive Infinity should not equal Negative Infinity", MathUtils.equals(Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY));

        // Test Zeroes (Note: in Java 0.0 == -0.0 is true)
        assertTrue("0.0 should equal -0.0", MathUtils.equals(0.0, -0.0));
    }
}
